### 2.3 Create Middleware for Correlation ID Binding

**Create AsyncLocalStorage context** (`src/context.js`):
```javascript
const { AsyncLocalStorage } = require('async_hooks');

const correlationIdStore = new AsyncLocalStorage();

function getStore() {
  return correlationIdStore.getStore() || {};
}

function getCorrelationId() {
  return getStore().correlationId;
}

function setCorrelationId(correlationId) {
  correlationIdStore.enterWith({ correlationId });
}

module.exports = {
  correlationIdStore,
  getStore,
  getCorrelationId,
  setCorrelationId
};
```

**Create Express middleware** (`src/middleware.js`):
```javascript
const { v4: uuidv4 } = require('uuid');
const pino = require('pino');
const { correlationIdStore } = require('./context');

const baseLogger = pino();

function loggingMiddleware(req, res, next) {
  // Extract or generate correlation ID
  const correlationId = req.headers['x-correlation-id'] || uuidv4();

  // Bind to AsyncLocalStorage for this request
  correlationIdStore.run({ correlationId }, () => {
    // Create child logger with correlation ID bound
    req.logger = baseLogger.child({ correlation_id: correlationId });

    // Add correlation ID to response headers (for clients)
    res.setHeader('X-Correlation-ID', correlationId);

    // Log request
    req.logger.info({
      method: req.method,
      path: req.path,
      ip: req.ip
    }, 'Incoming request');

    // Capture response
    const originalSend = res.send;
    res.send = function(data) {
      req.logger.info({
        status: res.statusCode,
        duration_ms: Date.now() - req.startTime
      }, 'Request completed');
      return originalSend.call(this, data);
    };

    req.startTime = Date.now();
    next();
  });
}

module.exports = loggingMiddleware;
```

**Integration with Express app**:
```javascript
const express = require('express');
const loggingMiddleware = require('./middleware');

const app = express();

// Add logging middleware early in chain
app.use(loggingMiddleware);

// Routes use req.logger automatically
app.get('/orders/:id', async (req, res) => {
  req.logger.info({ orderId: req.params.id }, 'Fetching order');
  const order = await fetchOrder(req.params.id);
  req.logger.info({ orderId: order.id }, 'Order fetched');
  res.json(order);
});

app.listen(3000, () => {
  console.log('Server started on port 3000');
});
```

