### 2.6 Error Handling and Structured Error Logs

**Error Logging Wrapper**:
```javascript
function logError(logger, error, message, context = {}) {
  const errorLog = {
    message,
    error_code: error.code || 'UNKNOWN_ERROR',
    error_message: error.message,
    ...context
  };

  // Include stack trace in development
  if (process.env.NODE_ENV !== 'production') {
    errorLog.stack_trace = error.stack;
  }

  logger.error(errorLog);
}

// Usage
try {
  await processPayment(order);
} catch (error) {
  logError(req.logger, error, 'Payment processing failed', {
    orderId: order.id,
    paymentGateway: 'stripe',
    retryCount: 0
  });

  res.status(500).json({ error: 'Payment failed' });
}
```

**Error Response Middleware**:
```javascript
app.use((error, req, res, next) => {
  const correlationId = req.logger ? getCorrelationId() : 'UNKNOWN';

  logError(req.logger || baseLogger, error, 'Unhandled error', {
    path: req.path,
    method: req.method,
    statusCode: error.statusCode || 500
  });

  res.status(error.statusCode || 500).json({
    error: error.message,
    correlation_id: correlationId
  });
});
```

