**Common Pattern: Background Job**:
```javascript
async function processOrderAsync(orderId) {
  const correlationId = getCorrelationId();

  correlationIdStore.run({ correlationId }, async () => {
    const logger = getLogger();

    logger.info({ orderId }, 'Starting async order processing');

    try {
      const result = await doExpensiveWork(orderId);

      logger.info({ orderId, result }, 'Order processing complete');
    } catch (error) {
      logger.error({ orderId, error: error.message }, 'Order processing failed');

      // Retry logic
      await scheduleRetry(orderId);
    }
  });
