**Common Pattern: Service-to-Service Call**:
```javascript
async function callDownstreamService(serviceName, endpoint, data) {
  const correlationId = getCorrelationId();
  const logger = getLogger();

  const startTime = Date.now();

  try {
    logger.debug({ service: serviceName }, 'Calling downstream service');

    const response = await axios.post(
      `http://${serviceName}:3000${endpoint}`,
      data,
      {
        headers: { 'X-Correlation-ID': correlationId }
      }
    );

    const duration = Date.now() - startTime;

    logger.info({
      service: serviceName,
      status: response.status,
      duration_ms: duration
    }, 'Downstream service call completed');

    return response.data;
  } catch (error) {
    const duration = Date.now() - startTime;

    logger.error({
      service: serviceName,
      error: error.message,
      status: error.response?.status,
      duration_ms: duration
    }, 'Downstream service call failed');

    throw error;
  }
}
```

