   283→
   284→**Create Express middleware** (`src/middleware.js`):
   285→```javascript
   286→const { v4: uuidv4 } = require('uuid');
   287→const pino = require('pino');
   288→const { correlationIdStore } = require('./context');
   289→
   290→const baseLogger = pino();
   291→
   292→function loggingMiddleware(req, res, next) {
   293→  // Extract or generate correlation ID
   294→  const correlationId = req.headers['x-correlation-id'] || uuidv4();
   295→
   296→  // Bind to AsyncLocalStorage for this request
   297→  correlationIdStore.run({ correlationId }, () => {
   298→    // Create child logger with correlation ID bound
   299→    req.logger = baseLogger.child({ correlation_id: correlationId });
   300→
   301→    // Add correlation ID to response headers (for clients)
   302→    res.setHeader('X-Correlation-ID', correlationId);
   303→
   304→    // Log request
   305→    req.logger.info({
   306→      method: req.method,
   307→      path: req.path,
   308→      ip: req.ip
   309→    }, 'Incoming request');
   310→
   311→    // Capture response
   312→    const originalSend = res.send;
   313→    res.send = function(data) {
   314→      req.logger.info({
   315→        status: res.statusCode,
   316→        duration_ms: Date.now() - req.startTime
   317→      }, 'Request completed');
   318→      return originalSend.call(this, data);
   319→    };
   320→
   321→    req.startTime = Date.now();
   322→    next();
   323→  });
   324→}
   325→
   326→module.exports = loggingMiddleware;
   327→```
