**[IMPROVED] Worker Threads** (if used):

> **CRITICAL FIX**: Worker threads run in separate V8 instances and cannot inherit parent's AsyncLocalStorage. Correlation ID must be explicitly passed as parameter.

```javascript
const { Worker } = require('worker_threads');
const { getCorrelationId, setCorrelationId } = require('./context');
const pino = require('pino');

const logger = pino();

function startWorker(task, data) {
  const correlationId = getCorrelationId();

  // Worker threads cannot share AsyncLocalStorage - must pass correlationId explicitly
  const worker = new Worker('./worker.js');

  worker.on('message', (message) => {
    // Re-establish context in parent thread for logging
    setCorrelationId(correlationId);
    logger.info({ task, result: message }, 'Worker task complete');
  });

  worker.on('error', (error) => {
    setCorrelationId(correlationId);
    logger.error({ task, error: error.message }, 'Worker task failed');
  });

  // CRITICAL: Pass correlationId explicitly to worker
  worker.postMessage({ task, data, correlationId });
}
```

**Create Worker File** (`worker.js`):

```javascript
const { parentPort } = require('worker_threads');
const { setCorrelationId, getCorrelationId } = require('./context');
const pino = require('pino');

const logger = pino();

// Receive message with correlationId from parent
parentPort.on('message', async (message) => {
  const { task, data, correlationId } = message;

  // CRITICAL: Set correlation ID in worker's context at start
  setCorrelationId(correlationId);

  try {
    logger.info({ task }, 'Worker starting task');

    // All logs automatically include correlation_id from context
    const result = await processTask(task, data);

    logger.info({ task, success: true }, 'Worker task completed');
    parentPort.postMessage({ success: true, result });
  } catch (error) {
    // Error logs also have correlation_id
    logger.error({ task, error: error.message }, 'Worker task failed');
    parentPort.postMessage({ success: false, error: error.message });
  }
});

async function processTask(task, data) {
  // Simulate work
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve({ processed: data });
    }, 1000);
  });
}
```

