**[IMPROVED] Unit Tests** (`tests/middleware.test.js`):

```javascript
const request = require('supertest');
const pino = require('pino');
const express = require('express');
const { v4: uuidv4, validate: validateUUID } = require('uuid');
const loggingMiddleware = require('../src/middleware');
const { getCorrelationId } = require('../src/context');

// Create test app
const createTestApp = () => {
  const app = express();
  app.use(loggingMiddleware);

  app.get('/test', (req, res) => {
    res.json({ correlationId: getCorrelationId() });
  });

  return app;
};

describe('Logging Middleware', () => {
  let app;

  beforeEach(() => {
    app = createTestApp();
  });

  it('should bind correlation_id from header', async () => {
    const testId = 'test-123-abc';

    const response = await request(app)
      .get('/test')
      .set('X-Correlation-ID', testId);

    expect(response.headers['x-correlation-id']).toBe(testId);
    expect(response.body.correlationId).toBe(testId);
  });

  it('should generate correlation_id if missing', async () => {
    const response = await request(app).get('/test');

    const correlationId = response.headers['x-correlation-id'];
    expect(validateUUID(correlationId)).toBe(true);
    expect(response.body.correlationId).toBe(correlationId);
  });

  it('should include correlation_id in response header', async () => {
    const testId = uuidv4();

    const response = await request(app)
      .get('/test')
      .set('X-Correlation-ID', testId);

    expect(response.headers['x-correlation-id']).toBe(testId);
  });
});
```

**[IMPROVED] Concurrent Request Isolation Tests** (CRITICAL):

```javascript
describe('Concurrent Request Isolation', () => {
  let app;
  const capturedLogs = [];

  beforeEach(() => {
    app = createTestApp();
    capturedLogs.length = 0;
  });

  it('should isolate correlation IDs across 100+ concurrent requests', async () => {
    const concurrentRequests = 120;
    const correlationIds = Array.from({ length: concurrentRequests }, () => uuidv4());

    // Send 120 concurrent requests with unique correlation IDs
    const promises = correlationIds.map(correlationId =>
      request(app)
        .get('/test')
        .set('X-Correlation-ID', correlationId)
    );

    const responses = await Promise.all(promises);

    // Verify each response has correct correlation ID
    responses.forEach((response, index) => {
      const expectedId = correlationIds[index];
      expect(response.body.correlationId).toBe(expectedId);
      expect(response.headers['x-correlation-id']).toBe(expectedId);
    });

    // Verify no context bleed - all IDs must be unique in responses
    const returnedIds = responses.map(r => r.body.correlationId);
    const uniqueIds = new Set(returnedIds);
    expect(uniqueIds.size).toBe(concurrentRequests);
  });

  it('should not allow context bleed from concurrent requests', async () => {
    const test1Id = uuidv4();
    const test2Id = uuidv4();

    const [response1, response2] = await Promise.all([
      request(app).get('/test').set('X-Correlation-ID', test1Id),
      request(app).get('/test').set('X-Correlation-ID', test2Id)
    ]);

    // Each must have its own ID, not the other's
    expect(response1.body.correlationId).toBe(test1Id);
    expect(response2.body.correlationId).toBe(test2Id);
    expect(response1.body.correlationId).not.toBe(response2.body.correlationId);
  });
});
```

**[IMPROVED] Error Scenario Tests** (CRITICAL):

```javascript
describe('Error Scenarios', () => {
  let app;

  beforeEach(() => {
    const expressApp = express();
    expressApp.use(loggingMiddleware);

    expressApp.get('/unhandled-error', () => {
      throw new Error('Unhandled exception');
    });

    expressApp.get('/timeout', async (req, res) => {
      await new Promise(resolve => setTimeout(resolve, 35000)); // Exceeds timeout
      res.json({ ok: true });
    });

    expressApp.get('/service-failure', async (req, res) => {
      // Simulate downstream service failure
      throw new Error('Database connection failed');
    });

    expressApp.use((error, req, res, next) => {
      const correlationId = getCorrelationId();
      res.status(500).json({
        error: error.message,
        correlation_id: correlationId
      });
    });

    app = expressApp;
  });

  it('should preserve correlation_id in unhandled exceptions', async () => {
    const testId = uuidv4();
    const response = await request(app)
      .get('/unhandled-error')
      .set('X-Correlation-ID', testId);

    expect(response.status).toBe(500);
    expect(response.body.correlation_id).toBe(testId);
    expect(response.body.error).toContain('Unhandled');
  });

  it('should preserve correlation_id in timeout errors', async () => {
    const testId = uuidv4();
    const response = await request(app)
      .get('/service-failure')
      .set('X-Correlation-ID', testId)
      .timeout(5000);

    expect(response.body.correlation_id).toBe(testId);
  });

  it('should preserve correlation_id in downstream service failures', async () => {
    const testId = uuidv4();
    const response = await request(app)
      .get('/service-failure')
      .set('X-Correlation-ID', testId);

    expect(response.status).toBe(500);
    expect(response.body.correlation_id).toBe(testId);
  });
});
