**[IMPROVED] Async Operations Tests**:

```javascript
describe('Async Operations', () => {
  let app;

  beforeEach(() => {
    const expressApp = express();
    expressApp.use(loggingMiddleware);

    let backgroundJobResults = [];

    expressApp.post('/background-job', async (req, res) => {
      const correlationId = getCorrelationId();

      // Fire background job without blocking response
      setImmediate(async () => {
        setCorrelationId(correlationId);
        backgroundJobResults.push({
          correlationId: getCorrelationId(),
          timestamp: Date.now()
        });
      });

      res.json({ status: 'accepted', correlation_id: correlationId });
    });

    expressApp.get('/background-results', (req, res) => {
      res.json(backgroundJobResults);
    });

    app = expressApp;
  });

  it('should preserve correlation_id in background jobs', async () => {
    const testId = uuidv4();

    const response = await request(app)
      .post('/background-job')
      .set('X-Correlation-ID', testId);

    expect(response.body.correlation_id).toBe(testId);

    // Wait for background job to complete
    await new Promise(resolve => setTimeout(resolve, 100));

    const results = await request(app).get('/background-results');
    expect(results.body.length).toBeGreaterThan(0);
    expect(results.body[0].correlationId).toBe(testId);
  });
});
```

**[IMPROVED] Integration Tests** - Service Boundary & Multi-hop Chains:

```javascript
describe('Service Propagation', () => {
  let app;

  beforeEach(() => {
    const expressApp = express();
    expressApp.use(loggingMiddleware);

    // Mock downstream services for testing
    expressApp.get('/call-downstream', async (req, res) => {
      const correlationId = getCorrelationId();

      try {
        // Simulate calling another service with correlation ID
        const result = await simulateDownstreamCall('inventory-service', '/check', correlationId);
        res.json(result);
      } catch (error) {
        res.status(500).json({ error: error.message, correlation_id: correlationId });
      }
    });

    app = expressApp;
  });

  it('should include correlation_id in downstream calls', async () => {
    const testId = uuidv4();
    const downstreamHeaders = {};

    // Intercept headers
    const originalAxios = require('axios');
    jest.spyOn(originalAxios, 'get').mockImplementation((url, config) => {
      Object.assign(downstreamHeaders, config.headers);
      return Promise.resolve({ data: { available: true } });
    });

    const response = await request(app)
      .get('/call-downstream')
      .set('X-Correlation-ID', testId);

    expect(downstreamHeaders['X-Correlation-ID']).toBe(testId);
  });

  it('should propagate correlation_id across multi-hop service chains', async () => {
    const testId = uuidv4();
    const hops = [];

    // Simulate 3-hop service chain
    const hop1 = request(app).get('/call-downstream').set('X-Correlation-ID', testId);
    hops.push(hop1);

    await new Promise(resolve => setTimeout(resolve, 100));

    hops.forEach(promise => {
      expect(promise.body.correlation_id).toBe(testId);
    });
  });
});

async function simulateDownstreamCall(service, endpoint, correlationId) {
  // Simulates calling downstream service with correlation ID in headers
  return Promise.resolve({ service, endpoint, available: true });
}
