import pino, { Logger, LoggerOptions } from 'pino';
import { getCorrelationId } from './correlationIdContext';

/**
 * Create a child logger instance with optional correlation ID
 * The logger automatically injects the correlation ID into all log entries
 */
export const createLogger = (moduleName: string): Logger => {
  const baseLogger = pino({
    name: moduleName,
    level: process.env.LOG_LEVEL || 'info',
    // Set up transport for pretty-printing in development
    transport:
      process.env.NODE_ENV === 'production'
        ? undefined
        : {
            target: 'pino-pretty',
            options: {
              colorize: true,
              translateTime: 'SYS:standard',
              ignore: 'pid,hostname',
            },
          },
  });

  // Return a proxy that injects correlation ID before logging
  return createChildLoggerWithContext(baseLogger);
};

/**
 * Create a child logger that automatically injects correlation ID
 * This ensures every log entry includes the current correlation ID
 */
function createChildLoggerWithContext(baseLogger: Logger): Logger {
  return {
    ...baseLogger,
    child: function (bindings) {
      const correlationId = getCorrelationId();
      const contextBindings = correlationId
        ? { ...bindings, correlationId }
        : bindings;
      return baseLogger.child(contextBindings);
    },
    // Wrap all logging methods to inject correlation ID
    trace: (msg: any, ...args: any[]) => {
      const correlationId = getCorrelationId();
      if (correlationId) {
        return baseLogger.trace({ correlationId }, msg, ...args);
      }
      return baseLogger.trace(msg, ...args);
    },
    debug: (msg: any, ...args: any[]) => {
      const correlationId = getCorrelationId();
      if (correlationId) {
        return baseLogger.debug({ correlationId }, msg, ...args);
      }
      return baseLogger.debug(msg, ...args);
    },
    info: (msg: any, ...args: any[]) => {
      const correlationId = getCorrelationId();
      if (correlationId) {
        return baseLogger.info({ correlationId }, msg, ...args);
      }
      return baseLogger.info(msg, ...args);
    },
    warn: (msg: any, ...args: any[]) => {
      const correlationId = getCorrelationId();
      if (correlationId) {
        return baseLogger.warn({ correlationId }, msg, ...args);
      }
      return baseLogger.warn(msg, ...args);
    },
    error: (msg: any, ...args: any[]) => {
      const correlationId = getCorrelationId();
      if (correlationId) {
        return baseLogger.error({ correlationId }, msg, ...args);
      }
      return baseLogger.error(msg, ...args);
    },
    fatal: (msg: any, ...args: any[]) => {
      const correlationId = getCorrelationId();
      if (correlationId) {
        return baseLogger.fatal({ correlationId }, msg, ...args);
      }
      return baseLogger.fatal(msg, ...args);
    },
  } as Logger;
}

/**
 * Get or create the default application logger
 * Used for application-level logging (startup, shutdown, etc.)
 */
let defaultLogger: Logger | null = null;

export const getDefaultLogger = (): Logger => {
  if (!defaultLogger) {
    defaultLogger = createLogger('app');
  }
  return defaultLogger;
};

/**
 * Define the standard log schema for all structured logs
 */
export interface StructuredLogEntry {
  timestamp: string; // ISO 8601
  level: 'trace' | 'debug' | 'info' | 'warn' | 'error' | 'fatal';
  correlationId?: string;
  service?: string;
  message: string;
  [key: string]: any; // Additional context fields
}
```

