```typescript
/**
 * Standard log schema for all structured logging
 * All API logs must conform to this structure
 */

export interface BaseLog {
  timestamp: string; // ISO 8601 format, e.g., "2026-04-03T20:30:00.000Z"
  level: 'trace' | 'debug' | 'info' | 'warn' | 'error' | 'fatal';
  correlationId: string; // Request trace ID, always included
  service: string; // Service/module name
  message: string; // Human-readable message
}

export interface RequestLog extends BaseLog {
  type: 'request_start' | 'request_complete';
  method: string; // HTTP method (GET, POST, etc.)
  path: string; // Request path
  statusCode?: number; // HTTP status code (only in request_complete)
  duration?: number; // Request duration in milliseconds (only in request_complete)
  userId?: string; // Authenticated user ID if available
  clientIp?: string; // Client IP address
}

export interface ErrorLog extends BaseLog {
  type: 'error';
  errorCode: string; // Application error code
  errorMessage: string; // Detailed error message
  stackTrace?: string; // Full stack trace
  errorContext?: Record<string, any>; // Additional error context
}

export interface DependencyLog extends BaseLog {
  type: 'dependency_call';
  dependencyName: string; // Name of external service/DB
  operation: string; // Operation being performed
  duration: number; // Operation duration in milliseconds
  status: 'success' | 'error' | 'timeout'; // Operation status
  dependencyContext?: Record<string, any>; // DB query, URL, etc.
}

export interface OperationLog extends BaseLog {
  type: 'operation';
  operation: string; // Business operation name
  status: 'started' | 'completed' | 'failed';
  duration?: number; // Operation duration in milliseconds
  operationContext?: Record<string, any>; // Operation-specific context
}

// Union type for all possible log types
export type StructuredLog =
  | RequestLog
  | ErrorLog
  | DependencyLog
  | OperationLog;

/**
 * Validation function to ensure logs conform to schema
 * Used in tests to validate log structure
 */
export const validateLog = (log: any): boolean => {
  return (
    log.timestamp &&
    log.level &&
    log.correlationId &&
    log.service &&
    log.message &&
    typeof log.timestamp === 'string' &&
    ['trace', 'debug', 'info', 'warn', 'error', 'fatal'].includes(log.level)
  );
};

/**
 * Default service name (can be overridden via environment)
 */
export const getServiceName = (): string => {
  return process.env.SERVICE_NAME || 'api-service';
};
```

**Success Markers:**
- TypeScript interfaces compile without errors
- All log types properly defined
- Validation function works correctly
- Can be imported and used in tests

