    57→```typescript
    58→import { AsyncLocalStorage } from 'async_hooks';
    59→
    60→// AsyncLocalStorage for managing correlation IDs across async boundaries
    61→const correlationIdStorage = new AsyncLocalStorage<string>();
    62→
    63→/**
    64→ * Get the current correlation ID from async context
    65→ * Returns undefined if no context is set
    66→ */
    67→export const getCorrelationId = (): string | undefined => {
    68→  return correlationIdStorage.getStore();
    69→};
    70→
    71→/**
    72→ * Set correlation ID for the current async context
    73→ * All async operations within this context will have access to this ID
    74→ */
    75→export const setCorrelationId = (id: string, callback: () => void): void => {
    76→  correlationIdStorage.run(id, callback);
    77→};
    78→
    79→/**
    80→ * Set correlation ID with async callback
    81→ * Useful for Promise-based operations
    82→ */
    83→export const setCorrelationIdAsync = <T>(
    84→  id: string,
    85→  callback: () => Promise<T>
    86→): Promise<T> => {
    87→  return new Promise((resolve, reject) => {
    88→    correlationIdStorage.run(id, async () => {
    89→      try {
    90→        const result = await callback();
    91→        resolve(result);
    92→      } catch (error) {
    93→        reject(error);
    94→      }
    95→    });
    96→  });
    97→};
    98→
    99→/**
   100→ * Export storage instance for middleware integration
   101→ */
   102→export { correlationIdStorage };
   103→```
