   255→/**
   256→ * Standard log schema for all structured logging
   257→ * All API logs must conform to this structure
   258→ */
   259→
   260→export interface BaseLog {
   261→  timestamp: string; // ISO 8601 format, e.g., "2026-04-03T20:30:00.000Z"
   262→  level: 'trace' | 'debug' | 'info' | 'warn' | 'error' | 'fatal';
   263→  correlationId: string; // Request trace ID, always included
   264→  service: string; // Service/module name
   265→  message: string; // Human-readable message
   266→}
   267→
   268→export interface RequestLog extends BaseLog {
   269→  type: 'request_start' | 'request_complete';
   270→  method: string; // HTTP method (GET, POST, etc.)
   271→  path: string; // Request path
   272→  statusCode?: number; // HTTP status code (only in request_complete)
   273→  duration?: number; // Request duration in milliseconds (only in request_complete)
   274→  userId?: string; // Authenticated user ID if available
   275→  clientIp?: string; // Client IP address
   276→}
   277→
   278→export interface ErrorLog extends BaseLog {
   279→  type: 'error';
   280→  errorCode: string; // Application error code
   281→  errorMessage: string; // Detailed error message
   282→  stackTrace?: string; // Full stack trace
   283→  errorContext?: Record<string, any>; // Additional error context
   284→}
   285→
   286→export interface DependencyLog extends BaseLog {
   287→  type: 'dependency_call';
   288→  dependencyName: string; // Name of external service/DB
   289→  operation: string; // Operation being performed
   290→  duration: number; // Operation duration in milliseconds
   291→  status: 'success' | 'error' | 'timeout'; // Operation status
   292→  dependencyContext?: Record<string, any>; // DB query, URL, etc.
   293→}
   294→
   295→export interface OperationLog extends BaseLog {
   296→  type: 'operation';
   297→  operation: string; // Business operation name
   298→  status: 'started' | 'completed' | 'failed';
   299→  duration?: number; // Operation duration in milliseconds
   300→  operationContext?: Record<string, any>; // Operation-specific context
   301→}
   302→
   303→// Union type for all possible log types
   304→export type StructuredLog =
   305→  | RequestLog
   306→  | ErrorLog
   307→  | DependencyLog
   308→  | OperationLog;
   309→
   310→/**
   311→ * Validation function to ensure logs conform to schema
   312→ * Used in tests to validate log structure
   313→ */
   314→export const validateLog = (log: any): boolean => {
   315→  return (
   316→    log.timestamp &&
   317→    log.level &&
   318→    log.correlationId &&
   319→    log.service &&
   320→    log.message &&
   321→    typeof log.timestamp === 'string' &&
   322→    ['trace', 'debug', 'info', 'warn', 'error', 'fatal'].includes(log.level)
   323→  );
   324→};
   325→
   326→/**
   327→ * Default service name (can be overridden via environment)
   328→ */
   329→export const getServiceName = (): string => {
   330→  return process.env.SERVICE_NAME || 'api-service';
   331→};
