### Step 1.2: Create Correlation ID Context Storage

**Action:** Implement AsyncLocalStorage-based context manager

**File:** `src/lib/correlationIdContext.ts`

```typescript
import { AsyncLocalStorage } from 'async_hooks';

// AsyncLocalStorage for managing correlation IDs across async boundaries
const correlationIdStorage = new AsyncLocalStorage<string>();

/**
 * Get the current correlation ID from async context
 * Returns undefined if no context is set
 */
export const getCorrelationId = (): string | undefined => {
  return correlationIdStorage.getStore();
};

/**
 * Set correlation ID for the current async context
 * All async operations within this context will have access to this ID
 */
export const setCorrelationId = (id: string, callback: () => void): void => {
  correlationIdStorage.run(id, callback);
};

/**
 * Set correlation ID with async callback
 * Useful for Promise-based operations
 */
export const setCorrelationIdAsync = <T>(
  id: string,
  callback: () => Promise<T>
): Promise<T> => {
  return new Promise((resolve, reject) => {
    correlationIdStorage.run(id, async () => {
