        dependencyName: serviceName,
        operation: `${response.config.method?.toUpperCase()} ${response.config.url}`,
        status: response.status < 400 ? 'success' : 'error',
        duration,
        statusCode: response.status,
        message: `${serviceName} responded with status ${response.status}`,
