import { Request, Response, NextFunction } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { setCorrelationIdAsync } from '../lib/correlationIdContext';
import { createLogger } from '../lib/loggerFactory';

declare global {
  namespace Express {
    interface Request {
      correlationId: string;
    }
    interface Response {
      sentAt: number;
    }
  }
}

/**
 * Express middleware to handle correlation IDs
 *
 * Flow:
 * 1. Extract X-Correlation-ID header from incoming request (if present)
 * 2. Generate new UUID if no header found
 * 3. Store in AsyncLocalStorage context for the entire request lifecycle
 * 4. Attach correlation ID to response headers
 * 5. Log request start with correlation ID
 */
export const correlationIdMiddleware = (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  // Extract correlation ID from incoming request or generate new one
  const incomingCorrelationId = req.headers['x-correlation-id'] as string;
  const correlationId = incomingCorrelationId || uuidv4();

  // Store on request object for easy access
  req.correlationId = correlationId;

  // Attach to response headers for downstream services
  res.setHeader('x-correlation-id', correlationId);
  res.sentAt = Date.now();

  // Set up async context for this request
  // All subsequent code in the request handler has access to this correlation ID
  setCorrelationIdAsync(correlationId, async () => {
    // Log the incoming request
    const logger = createLogger('http');
    logger.info({
      type: 'request_start',
      method: req.method,
      path: req.path,
      clientIp: req.ip || req.connection.remoteAddress,
      message: `Incoming ${req.method} request to ${req.path}`,
    });

    // Call next middleware
    next();
  }).catch((error) => {
    // Handle any errors in context
    const logger = createLogger('http');
    logger.error({
      type: 'error',
      errorCode: 'MIDDLEWARE_ERROR',
      errorMessage: 'Error in correlation ID middleware',
      message: error.message,
      stackTrace: error.stack,
    });
    next(error);
  });
};

/**
 * Middleware to log request completion
 * Must be applied after all route handlers
 * Logs response status, duration, and other metadata
 */
export const requestCompletionLoggingMiddleware = (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  // Hook into res.send() to capture when response is sent
  const originalSend = res.send;

  res.send = function (data: any) {
    const logger = createLogger('http');
    const duration = Date.now() - (res.sentAt || Date.now());

    logger.info({
      type: 'request_complete',
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration,
      message: `${req.method} ${req.path} completed with status ${res.statusCode}`,
    });

    return originalSend.call(this, data);
  };

  next();
};

