### Pre-Phase 1: Critical Issue Remediation (REQUIRED)

**Duration:** 3-4 hours
**Status:** BLOCKING - Must complete before Phase 1 steps

This section addresses 6 critical architectural issues identified in synthesis review. Implementing these fixes upfront prevents 3-5 hours of debugging during Phase 2.

#### Issue 1: AsyncLocalStorage Context Wrappers for Promise Concurrency

**Problem:** AsyncLocalStorage does not automatically maintain context across Promise.all(), Promise.race(), and Promise.allSettled(). Parallel operations lose correlation ID context.

**Solution:** Implement explicit context wrapping utilities.

**File:** `src/lib/asyncContextWrappers.ts`

```typescript
import { AsyncLocalStorage } from 'async_hooks';
import { getCorrelationId, correlationIdStorage } from './correlationIdContext';

/**
 * Wrap a Promise to execute within the current AsyncLocalStorage context
 * Use this when creating promises that need access to correlation ID
 */
export const withContext = <T>(
  promise: Promise<T>,
  context?: string
): Promise<T> => {
  const ctxValue = context || getCorrelationId();
  if (!ctxValue) {
    return promise; // No context to preserve
  }

  return new Promise((resolve, reject) => {
    correlationIdStorage.run(ctxValue, () => {
      promise.then(resolve).catch(reject);
    });
  });
};

/**
 * Wrap multiple promises for Promise.all() with context preservation
 * CRITICAL: Pass promises as wrapped versions
 */
export const withContextAll = <T>(
  promises: Promise<T>[]
): Promise<T[]> => {
  const context = getCorrelationId();
  if (!context) {
    return Promise.all(promises);
  }

  const wrappedPromises = promises.map(promise =>
    new Promise<T>((resolve, reject) => {
      correlationIdStorage.run(context, () => {
        promise.then(resolve).catch(reject);
      });
    })
  );

  return Promise.all(wrappedPromises);
};

/**
 * Wrap multiple promises for Promise.race() with context preservation
 */
export const withContextRace = <T>(
  promises: Promise<T>[]
): Promise<T> => {
  const context = getCorrelationId();
  if (!context) {
    return Promise.race(promises);
  }

  const wrappedPromises = promises.map(promise =>
    new Promise<T>((resolve, reject) => {
      correlationIdStorage.run(context, () => {
        promise.then(resolve).catch(reject);
      });
    })
  );

  return Promise.race(wrappedPromises);
};

/**
 * Wrap multiple promises for Promise.allSettled() with context preservation
 */
export const withContextAllSettled = <T>(
  promises: Promise<T>[]
): Promise<PromiseSettledResult<T>[]> => {
  const context = getCorrelationId();
  if (!context) {
    return Promise.allSettled(promises);
  }

  const wrappedPromises = promises.map(promise =>
    new Promise<T>((resolve, reject) => {
      correlationIdStorage.run(context, () => {
        promise.then(resolve).catch(reject);
      });
    })
  );

  return Promise.allSettled(wrappedPromises);
};
```

**Documentation:** When using Promise.all/race/allSettled with async operations that need correlation ID:
- Single promise: Use `withContext(promise)`
- Multiple promises: Use `withContextAll(promises)`, `withContextRace(promises)`, or `withContextAllSettled(promises)`
- Example:
  ```typescript
  // DON'T: This loses context
  const results = await Promise.all([op1(), op2(), op3()]);

  // DO: This preserves context
  const results = await withContextAll([op1(), op2(), op3()]);
  ```

#### Issue 2: Express Middleware Async Flow Correction

**Problem:** The current middleware calls `next()` inside an awaited callback, breaking Express middleware execution flow. Express expects middleware to complete synchronously or return a Promise that resolves when middleware is done.

**Solution:** Store correlation ID context at request start, use `res.on('finish')` callback for logging.

**File:** `src/middleware/correlationIdMiddleware.ts` (Step 2.1 to be updated)

```typescript
import { Request, Response, NextFunction } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { setCorrelationIdAsync, getCorrelationId } from '../lib/correlationIdContext';
import { createLogger } from '../lib/loggerFactory';

declare global {
  namespace Express {
    interface Request {
      correlationId: string;
    }
    interface Response {
      sentAt: number;
      correlationIdContext?: string;
    }
  }
}

/**
 * CRITICAL UPDATE: Proper Express middleware pattern
 * Handles correlation ID setup synchronously, uses async context for all handlers
 */
export const correlationIdMiddleware = (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  // Extract or generate correlation ID SYNCHRONOUSLY
  const incomingCorrelationId = req.headers['x-correlation-id'] as string;
  const correlationId = incomingCorrelationId || uuidv4();

  // Store on request/response for middleware access
  req.correlationId = correlationId;
  res.correlationIdContext = correlationId;
  res.setHeader('x-correlation-id', correlationId);
  res.sentAt = Date.now();

  // Wrap the rest of the middleware chain in async context
  // This ensures all downstream handlers have access to correlation ID
  setCorrelationIdAsync(correlationId, async () => {
    // Call next synchronously, but all handlers run within context
    return new Promise<void>((resolve, reject) => {
      // Handle response completion to log with correlation ID
      res.on('finish', () => {
        const logger = createLogger('http');
        const duration = Date.now() - (res.sentAt || Date.now());

        logger.info({
          type: 'request_complete',
          method: req.method,
          path: req.path,
          statusCode: res.statusCode,
          duration,
          message: `${req.method} ${req.path} completed with status ${res.statusCode} in ${duration}ms`,
        });

        resolve();
      });

      // Handle errors
      res.on('error', (error) => {
        const logger = createLogger('http');
        logger.error({
          type: 'error',
          errorCode: 'RESPONSE_ERROR',
          errorMessage: 'Error during response',
          message: error.message,
          stackTrace: error.stack,
        });
        reject(error);
      });

      // Log request start
      const logger = createLogger('http');
      logger.info({
        type: 'request_start',
        method: req.method,
        path: req.path,
        clientIp: req.ip || (req.socket as any).remoteAddress,
        message: `Incoming ${req.method} request to ${req.path}`,
      });

      // Call next to continue middleware chain
      next();
    });
  }).catch((error) => {
    const logger = createLogger('http');
    logger.error({
      type: 'error',
      errorCode: 'MIDDLEWARE_ERROR',
      errorMessage: 'Unhandled error in correlation ID middleware',
      message: error.message,
      stackTrace: error.stack,
    });
    next(error);
  });
};
```

#### Issue 3: Logger Factory - Use Pino's Native child() Method

**Problem:** Current implementation monkey-patches Pino logger with a proxy pattern, bypassing TypeScript type safety and missing methods. This violates type safety and creates maintenance burden.

**Solution:** Use Pino's native `child()` method with context injection at log time.

**File:** `src/lib/loggerFactory.ts` (Step 1.3 to be updated)

```typescript
import pino, { Logger, LoggerOptions } from 'pino';
import { getCorrelationId } from './correlationIdContext';

/**
 * CRITICAL UPDATE: Use Pino's native child() method instead of proxy pattern
 * This maintains TypeScript type safety and Pino compatibility
 */
export const createLogger = (moduleName: string): Logger => {
  const baseLogger = pino({
    name: moduleName,
    level: process.env.LOG_LEVEL || 'info',
    transport:
      process.env.NODE_ENV === 'production'
        ? undefined
        : {
            target: 'pino-pretty',
            options: {
              colorize: true,
              translateTime: 'SYS:standard',
              ignore: 'pid,hostname',
            },
          },
  });

  // Return child logger with correlation ID binding
  return baseLogger.child(
    {
      // Correlation ID will be injected dynamically
      correlationId: getCorrelationId() || undefined,
    },
    {
      // Use msgPrefix to include module context in all logs
      msgPrefix: `[${moduleName}] `,
    }
  );
};

/**
 * Wrapper function to inject correlation ID into logger calls
 * Use when you need to ensure correlation ID is current at log time
 */
export const createContextAwareLogger = (moduleName: string): Logger => {
  const baseLogger = pino({
    name: moduleName,
    level: process.env.LOG_LEVEL || 'info',
  });

  // Create child with mixin function that captures correlation ID at log time
  return baseLogger.child(
    {},
    {
      msgPrefix: `[${moduleName}] `,
      mixin() {
        return {
          correlationId: getCorrelationId(),
        };
      },
    }
  );
};

/**
 * Get or create the default application logger
 */
let defaultLogger: Logger | null = null;

export const getDefaultLogger = (): Logger => {
  if (!defaultLogger) {
    defaultLogger = createContextAwareLogger('app');
  }
  return defaultLogger;
};

/**
 * Define the standard log schema for all structured logs
 */
export interface StructuredLogEntry {
  timestamp: string; // ISO 8601
  level: 'trace' | 'debug' | 'info' | 'warn' | 'error' | 'fatal';
  correlationId?: string;
  service?: string;
  message: string;
  [key: string]: any; // Additional context fields
}
