import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios';
import { getCorrelationId } from './correlationIdContext';
import { createLogger } from './loggerFactory';

/**
 * Create HTTP client with automatic correlation ID injection
 * All outgoing requests will include X-Correlation-ID header
 * Useful for service-to-service communication
 */
export const createHttpClient = (serviceName: string): AxiosInstance => {
  const logger = createLogger('http-client');
  const client = axios.create();

  // Request interceptor: inject correlation ID into all outgoing requests
  client.interceptors.request.use((config) => {
    const correlationId = getCorrelationId();

    if (correlationId) {
      // Add correlation ID header to outgoing request
      config.headers = config.headers || {};
      config.headers['x-correlation-id'] = correlationId;
    }

    // Log outgoing request
    logger.info({
      type: 'dependency_call',
      dependencyName: serviceName,
      operation: `${config.method?.toUpperCase()} ${config.url}`,
      status: 'started',
      message: `Making ${config.method?.toUpperCase()} request to ${serviceName}`,
    });

    // Store request start time for duration calculation
    (config as any).startTime = Date.now();

    return config;
  });

  // Response interceptor: log response with duration
  client.interceptors.response.use(
    (response) => {
      const duration = Date.now() - ((response.config as any).startTime || 0);
      const correlationId = getCorrelationId();

      logger.info({
        type: 'dependency_call',
        dependencyName: serviceName,
        operation: `${response.config.method?.toUpperCase()} ${response.config.url}`,
        status: response.status < 400 ? 'success' : 'error',
        duration,
        statusCode: response.status,
        message: `${serviceName} responded with status ${response.status}`,
      });

      return response;
    },
    (error) => {
      const duration = Date.now() - ((error.config?.startTime as any) || 0);
      const correlationId = getCorrelationId();

      logger.error({
        type: 'dependency_call',
        dependencyName: serviceName,
        operation: `${error.config?.method?.toUpperCase()} ${error.config?.url}`,
        status: 'error',
        duration,
        errorCode: error.code || 'HTTP_ERROR',
        errorMessage: error.message,
        message: `Error calling ${serviceName}: ${error.message}`,
      });

      return Promise.reject(error);
    }
  );

  return client;
};

/**
 * Global HTTP clients for common services
 * Create clients for each service you call
 */
const httpClients: Map<string, AxiosInstance> = new Map();

/**
 * Get or create an HTTP client for a service
 */
export const getHttpClient = (serviceName: string): AxiosInstance => {
  if (!httpClients.has(serviceName)) {
    httpClients.set(serviceName, createHttpClient(serviceName));
  }
  return httpClients.get(serviceName)!;
};
