```typescript
import got, { Got, HTTPError } from 'got';
import { getCorrelationId } from './correlationIdContext';
import { createLogger } from './loggerFactory';

/**
 * CRITICAL UPDATE: Using 'got' instead of axios
 * Reasons:
 * 1. Native Promise/async-await support (better with AsyncLocalStorage)
 * 2. Built-in retry with exponential backoff
 * 3. Automatic connection pooling
 * 4. Simpler API and better type safety
 * 5. Superior context preservation in concurrent scenarios
 */

// Global timeout configuration
const TIMEOUTS = {
  connect: 5000,    // Time to establish connection
  socket: 30000,    // Time for response after connection
  request: 60000,   // Total request time (including retries)
};

// Retry configuration
const RETRY_CONFIG = {
  limit: 3,
  methods: ['GET', 'HEAD', 'OPTIONS', 'PUT', 'DELETE'],
  statusCodes: [408, 429, 500, 502, 503, 504],
  errorCodes: ['ECONNREFUSED', 'ECONNRESET', 'ETIMEDOUT', 'EHOSTUNREACH'],
  backoffType: 'exponential' as const,
};

/**
 * Create HTTP client with automatic correlation ID injection
 * All outgoing requests will include X-Correlation-ID header
 * Useful for service-to-service communication
 */
export const createHttpClient = (serviceName: string): Got => {
  const logger = createLogger('http-client');

  return got.extend({
    // Timeout configuration
    timeout: TIMEOUTS,

    // Retry configuration
    retry: RETRY_CONFIG,

    // HTTP/2 support for better performance
    http2: false,

    // Request hooks for logging and context injection
    hooks: {
      beforeRequest: [
        (options) => {
          const correlationId = getCorrelationId();

          // Inject correlation ID into all requests
          if (correlationId) {
            options.headers = options.headers || {};
            options.headers['x-correlation-id'] = correlationId;
          }

          // Log outgoing request
          logger.info({
            type: 'dependency_call',
            dependencyName: serviceName,
            operation: `${options.method?.toUpperCase()} ${options.url}`,
            status: 'started',
            message: `Making ${options.method?.toUpperCase()} request to ${serviceName}`,
          });

          // Store request start time for duration calculation
          (options as any).startTime = Date.now();
        },
      ],

      afterResponse: [
        (response) => {
          const duration = Date.now() - ((response.request.options as any).startTime || 0);
          const correlationId = getCorrelationId();

          logger.info({
            type: 'dependency_call',
            dependencyName: serviceName,
            operation: `${response.request.method} ${response.request.url.href}`,
            status: response.statusCode < 400 ? 'success' : 'error',
            duration,
            statusCode: response.statusCode,
            message: `${serviceName} responded with status ${response.statusCode} in ${duration}ms`,
          });

          return response;
        },
      ],

      beforeError: [
        (error) => {
          const duration = Date.now() - ((error.request?.options as any).startTime || 0);
          const correlationId = getCorrelationId();

          if (error instanceof HTTPError) {
            logger.error({
              type: 'dependency_call',
              dependencyName: serviceName,
              operation: `${error.request.method} ${error.request.url.href}`,
              status: 'error',
              duration,
              statusCode: error.response?.statusCode,
              errorCode: error.code || 'HTTP_ERROR',
              errorMessage: error.message,
              message: `Error calling ${serviceName}: ${error.message}`,
            });
          } else {
            logger.error({
              type: 'dependency_call',
              dependencyName: serviceName,
              operation: 'unknown',
              status: 'error',
              duration,
              errorCode: (error as any).code || 'NETWORK_ERROR',
              errorMessage: error.message,
              message: `Network error calling ${serviceName}: ${error.message}`,
            });
          }

          return error;
        },
      ],
    },

    // Automatic JSON handling
    responseType: 'json',
  });
};

/**
 * Global HTTP clients for common services
 * Create clients for each service you call
 */
const httpClients: Map<string, Got> = new Map();

/**
 * Get or create an HTTP client for a service
 */
export const getHttpClient = (serviceName: string): Got => {
  if (!httpClients.has(serviceName)) {
    httpClients.set(serviceName, createHttpClient(serviceName));
  }
  return httpClients.get(serviceName)!;
};

/**
 * Usage example:
 *
 * const userServiceClient = getHttpClient('user-service');
 *
 * try {
