   230→
   231→  // Wrap the rest of the middleware chain in async context
   232→  // This ensures all downstream handlers have access to correlation ID
   233→  setCorrelationIdAsync(correlationId, async () => {
   234→    // Call next synchronously, but all handlers run within context
   235→    return new Promise<void>((resolve, reject) => {
   236→      // Handle response completion to log with correlation ID
   237→      res.on('finish', () => {
   238→        const logger = createLogger('http');
   239→        const duration = Date.now() - (res.sentAt || Date.now());
   240→
   241→        logger.info({
   242→          type: 'request_complete',
   243→          method: req.method,
   244→          path: req.path,
   245→          statusCode: res.statusCode,
   246→          duration,
   247→          message: `${req.method} ${req.path} completed with status ${res.statusCode} in ${duration}ms`,
   248→        });
   249→
   250→        resolve();
   251→      });
   252→
   253→      // Handle errors
   254→      res.on('error', (error) => {
   255→        const logger = createLogger('http');
   256→        logger.error({
   257→          type: 'error',
   258→          errorCode: 'RESPONSE_ERROR',
   259→          errorMessage: 'Error during response',
   260→          message: error.message,
   261→          stackTrace: error.stack,
   262→        });
   263→        reject(error);
   264→      });
   265→
   266→      // Log request start
   267→      const logger = createLogger('http');
   268→      logger.info({
   269→        type: 'request_start',
   270→        method: req.method,
   271→        path: req.path,
   272→        clientIp: req.ip || (req.socket as any).remoteAddress,
   273→        message: `Incoming ${req.method} request to ${req.path}`,
   274→      });
   275→
   276→      // Call next to continue middleware chain
   277→      next();
   278→    });
   279→  }).catch((error) => {
