 * This factory uses Pino's native child() method for type safety.
 */
export const createLogger = (moduleName: string): Logger => {
  const baseLogger = pino({
    name: moduleName,
    level: process.env.LOG_LEVEL || 'info',
    // Set up transport for pretty-printing in development
    transport:
      process.env.NODE_ENV === 'production'
        ? undefined
        : {
            target: 'pino-pretty',
            options: {
              colorize: true,
              translateTime: 'SYS:standard',
              ignore: 'pid,hostname',
            },
          },
  });

  // Return child logger with correlation ID binding
  return baseLogger.child(
    {
      // Correlation ID will be injected dynamically
      correlationId: getCorrelationId() || undefined,
    },
    {
      // Use msgPrefix to include module context in all logs
      msgPrefix: `[${moduleName}] `,
    }
  );
};

/**
