describe('Promise.allSettled() Context Preservation - Edge Cases', () => {
  it('should maintain context with mixed success/failure in allSettled', async () => {
    const testId = 'settled-test-id';

    await setCorrelationIdAsync(testId, async () => {
      const promises = [
        Promise.resolve(getCorrelationId()),
        Promise.reject(new Error('intentional failure')).catch(() => null),
        new Promise<string>((resolve) => {
          setTimeout(() => resolve(getCorrelationId() || 'LOST'), 5);
        }),
      ];

      const results = await withContextAllSettled(promises);

      expect(results[0].status).toBe('fulfilled');
      if (results[0].status === 'fulfilled') {
        expect(results[0].value).toBe(testId);
      }

      expect(results[2].status).toBe('fulfilled');
      if (results[2].status === 'fulfilled') {
        expect(results[2].value).toBe(testId);
      }
    });
  });

  it('should preserve correlation ID in 80% success + 20% failure mixed scenario', async () => {
    const testId = 'mixed-scenario-test-id';
    const results = { success: 0, failure: 0, contextLoss: 0 };

    await setCorrelationIdAsync(testId, async () => {
      const promises = Array.from({ length: 50 }, (_, i) => {
        // 80% success (40/50), 20% failure (10/50)
        if (i % 5 === 0) {
          return Promise.reject(new Error(`Intentional failure ${i}`));
        }
        return new Promise<string>((resolve) => {
          setTimeout(() => {
            const currentId = getCorrelationId();
            resolve(currentId || 'LOST');
          }, Math.random() * 10);
        });
      });

      const allResults = await withContextAllSettled(promises);

      allResults.forEach((result) => {
        if (result.status === 'fulfilled') {
          results.success++;
          if (result.value !== testId) {
            results.contextLoss++;
          }
        } else {
          results.failure++;
        }
      });
    });

    // Verify 40 successes, 10 failures
    expect(results.success).toBe(40);
    expect(results.failure).toBe(10);
    // Verify NO context loss in success cases
    expect(results.contextLoss).toBe(0);
  });

  it('should preserve correlation ID for both resolved AND rejected promises', async () => {
    const testId = 'resolved-rejected-test-id';
    const resolvedContexts: string[] = [];
    const rejectedContexts: string[] = [];

    await setCorrelationIdAsync(testId, async () => {
      const promises = [
        Promise.resolve(null).then(() => {
          resolvedContexts.push(getCorrelationId() || 'LOST');
        }),
        Promise.reject(new Error('test')).catch(() => {
          rejectedContexts.push(getCorrelationId() || 'LOST');
        }),
        new Promise((resolve, reject) => {
          setTimeout(() => {
            rejectedContexts.push(getCorrelationId() || 'LOST');
            reject(new Error('test'));
          }, 5);
        }).catch(() => null),
      ];

      await Promise.allSettled(promises);
    });

    // Both resolved and rejected paths should have access to correlation ID
    expect(resolvedContexts).toContain(testId);
    expect(rejectedContexts).toContain(testId);
  });
});

