### Step 1.7b: Error Middleware Context Loss Test

**Action:** Add test scenarios for error middleware when context is lost or middleware order is wrong

**File:** `src/middleware/__tests__/errorLoggingMiddleware.test.ts`

```typescript
import { errorLoggingMiddleware } from '../errorLoggingMiddleware';
import { correlationIdMiddleware } from '../correlationIdMiddleware';
import { setCorrelationIdAsync, getCorrelationId } from '../../lib/correlationIdContext';
import { Request, Response } from 'express';
import { v4 as uuidv4 } from 'uuid';

describe('Error Middleware Context Loss - Recovery Path', () => {
  it('should generate UUID fallback when correlation ID context is lost', async () => {
    const mockReq = {
      headers: {},
      method: 'GET',
      path: '/api/test',
      correlationId: undefined, // Context lost - no ID in request
    } as any as Request;

    const jsonResponse: any = {};
    const mockRes = {
      status: jest.fn().mockReturnThis(),
      json: jest.fn((data) => {
        Object.assign(jsonResponse, data);
      }),
    } as any as Response;

    const mockError = new Error('Test error - context lost');
    const mockNext = jest.fn();

    // Call error handler with lost context
    errorLoggingMiddleware(mockError, mockReq, mockRes, mockNext);

    // Verify response includes a correlation ID (should be UUID)
    expect(jsonResponse.correlationId).toBeDefined();
    // Verify it's a valid UUID format (contains dashes)
    expect(jsonResponse.correlationId).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
    );
  });

  it('should use request.correlationId fallback when context unavailable', async () => {
    const requestId = 'request-stored-id-12345';
    const mockReq = {
      headers: {},
      method: 'POST',
      path: '/api/users',
      correlationId: requestId, // ID stored on request
    } as any as Request;

    const jsonResponse: any = {};
    const mockRes = {
      status: jest.fn().mockReturnThis(),
      json: jest.fn((data) => {
        Object.assign(jsonResponse, data);
      }),
    } as any as Response;

    const mockError = new Error('Database error');
    const mockNext = jest.fn();

    // Call error handler without async context
    errorLoggingMiddleware(mockError, mockReq, mockRes, mockNext);

    // Verify it uses the request.correlationId
    expect(jsonResponse.correlationId).toBe(requestId);
  });

  it('should prefer AsyncLocalStorage context over fallbacks', async () => {
    const contextId = 'async-context-id-789';
    const requestId = 'request-id-456';

    const mockReq = {
      headers: {},
      method: 'DELETE',
      path: '/api/items/1',
      correlationId: requestId,
    } as any as Request;

    let capturedCorrelationId: string | undefined;

    const mockRes = {
      status: jest.fn().mockReturnThis(),
      json: jest.fn((data) => {
        capturedCorrelationId = data.correlationId;
      }),
    } as any as Response;

    const mockError = new Error('Item not found');
    const mockNext = jest.fn();

    // Call error handler WITHIN async context
    await setCorrelationIdAsync(contextId, async () => {
      errorLoggingMiddleware(mockError, mockReq, mockRes, mockNext);
    });

    // Verify it prioritizes context over request ID
    expect(capturedCorrelationId).toBe(contextId);
  });

  it('should provide valid correlation ID in all error scenarios', async () => {
    const scenarios = [
      { name: 'TypeError', error: new TypeError('Invalid type') },
      { name: 'RangeError', error: new RangeError('Out of range') },
      { name: 'Custom Error', error: { message: 'Custom error', status: 400 } },
      { name: 'No message', error: {} },
    ];

    for (const scenario of scenarios) {
      const mockReq = {
        headers: {},
        method: 'GET',
        path: '/api/test',
        correlationId: undefined,
      } as any as Request;

      const jsonResponse: any = {};
      const mockRes = {
        status: jest.fn().mockReturnThis(),
        json: jest.fn((data) => {
          Object.assign(jsonResponse, data);
        }),
      } as any as Response;

      const mockNext = jest.fn();

      // No async context, no request ID - forces UUID generation
      errorLoggingMiddleware(scenario.error, mockReq, mockRes, mockNext);

      // Verify every scenario gets a valid correlation ID
      expect(jsonResponse.correlationId).toBeDefined();
      expect(typeof jsonResponse.correlationId).toBe('string');
      expect(jsonResponse.correlationId.length).toBeGreaterThan(0);
    }
  });
});
```

