   212→/**
   213→ * CRITICAL UPDATE: Proper Express middleware pattern
   214→ * Handles correlation ID setup synchronously, uses async context for all handlers
   215→ *
   216→ * IMPORTANT: res.on('finish') callbacks automatically execute within the
   217→ * setCorrelationIdAsync context, preserving correlation ID through the entire
   218→ * request lifecycle including streaming completion and response finish handlers.
   219→ *
   220→ * This works because Node.js maintains the AsyncLocalStorage context across
   221→ * event loop iterations when callbacks are registered before context exits.
   222→ * The getCorrelationId() function is guaranteed to return the correct ID in
   223→ * finish/error callbacks because they execute within the async context scope.
   224→ */
   225→export const correlationIdMiddleware = (
   226→  req: Request,
   227→  res: Response,
   228→  next: NextFunction
   229→) => {
   230→  // Extract or generate correlation ID SYNCHRONOUSLY
   231→  const incomingCorrelationId = req.headers['x-correlation-id'] as string;
   232→  const correlationId = incomingCorrelationId || uuidv4();
   233→
   234→  // Store on request/response for middleware access
   235→  req.correlationId = correlationId;
   236→  res.correlationIdContext = correlationId;
   237→  res.setHeader('x-correlation-id', correlationId);
   238→  res.sentAt = Date.now();
   239→
   240→  // Wrap the rest of the middleware chain in async context
   241→  // This ensures all downstream handlers have access to correlation ID
   242→  setCorrelationIdAsync(correlationId, async () => {
   243→    // Call next synchronously, but all handlers run within context
   244→    return new Promise<void>((resolve, reject) => {
   245→      // Handle response completion to log with correlation ID
   246→      res.on('finish', () => {
   247→        const logger = createLogger('http');
   248→        const duration = Date.now() - (res.sentAt || Date.now());
   249→
   250→        logger.info({
   251→          type: 'request_complete',
   252→          method: req.method,
   253→          path: req.path,
   254→          statusCode: res.statusCode,
   255→          duration,
   256→          message: `${req.method} ${req.path} completed with status ${res.statusCode} in ${duration}ms`,
   257→        });
   258→
   259→        resolve();
   260→      });
   261→
   262→      // Handle errors
   263→      res.on('error', (error) => {
   264→        const logger = createLogger('http');
   265→        logger.error({
   266→          type: 'error',
   267→          errorCode: 'RESPONSE_ERROR',
   268→          errorMessage: 'Error during response',
   269→          message: error.message,
   270→          stackTrace: error.stack,
   271→        });
   272→        reject(error);
   273→      });
   274→
   275→      // Log request start
   276→      const logger = createLogger('http');
   277→      logger.info({
   278→        type: 'request_start',
   279→        method: req.method,
   280→        path: req.path,
   281→        clientIp: req.ip || (req.socket as any).remoteAddress,
   282→        message: `Incoming ${req.method} request to ${req.path}`,
   283→      });
   284→
   285→      // Call next to continue middleware chain
   286→      next();
   287→    });
   288→  }).catch((error) => {
   289→    const logger = createLogger('http');
   290→    logger.error({
   291→      type: 'error',
   292→      errorCode: 'MIDDLEWARE_ERROR',
   293→      errorMessage: 'Unhandled error in correlation ID middleware',
   294→      message: error.message,
   295→      stackTrace: error.stack,
   296→    });
   297→    next(error);
   298→  });
   299→};
