## Pattern 2: Async-Safe Context Pattern (Recommended for Node.js)

**Effort:** Medium (4-6 hours)
**Complexity:** Medium
**Dependencies:** None (uses built-in async_hooks)

**Implementation:**
```javascript
// correlation-context.js
const asyncHooks = require('async_hooks');
const { v4: uuid } = require('uuid');

const asyncLocalStorage = new asyncHooks.AsyncLocalStorage();

module.exports = {
  getCorrelationId: () => asyncLocalStorage.getStore(),

  setCorrelationId: (id) => {
    return asyncLocalStorage.run(id, () => id);
  },

  withCorrelationId: (id, fn) => {
    return new Promise((resolve, reject) => {
      asyncLocalStorage.run(id, async () => {
        try {
          resolve(await fn());
        } catch (err) {
          reject(err);
        }
      });
    });
  }
};

// middleware.js
const express = require('express');
const { getCorrelationId, withCorrelationId } = require('./correlation-context');

const correlationMiddleware = (req, res, next) => {
  const correlationId = req.get('X-Correlation-ID') || uuid();

  withCorrelationId(correlationId, () => {
    res.set('X-Correlation-ID', correlationId);
    next();
  });
};

// logger.js
const winston = require('winston');
const { getCorrelationId } = require('./correlation-context');

const logger = winston.createLogger({
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.printf(({ timestamp, level, message, ...meta }) => {
      const correlationId = getCorrelationId();
      return JSON.stringify({
        timestamp,
        level,
        correlation_id: correlationId,
        message,
        ...meta
      });
    })
  ),
  transports: [new winston.transports.Console()]
});

// service.js - No need to pass correlation_id as parameter
const processOrder = async (orderId) => {
  logger.info('Processing order', { orderId }); // Includes correlation_id automatically

  // Calling another service
  const response = await fetch('http://payment-service/api/charge', {
    headers: {
      'X-Correlation-ID': getCorrelationId()
    }
  });
};
```

**Pros:**
- Propagates automatically across async boundaries
- No need to pass correlation ID through all function parameters
- Cleaner code
- True async-safe implementation

**Cons:**
- Requires understanding of async_hooks
- Slightly higher memory overhead
- Only works in Node.js

