2. **Create Correlation ID Servlet Filter**
   ```java
   import org.slf4j.MDC;
   import jakarta.servlet.*;
   import java.io.IOException;
   import java.util.UUID;

   public class CorrelationIdFilter implements Filter {
       private static final String CORRELATION_ID_HEADER = "X-Correlation-ID";
       private static final String CORRELATION_ID_MDC = "correlation_id";

       @Override
       public void doFilter(ServletRequest request, ServletResponse response,
                           FilterChain chain) throws IOException, ServletException {
           HttpServletRequest httpRequest = (HttpServletRequest) request;
           String correlationId = httpRequest.getHeader(CORRELATION_ID_HEADER);

           if (correlationId == null || correlationId.isEmpty()) {
               correlationId = UUID.randomUUID().toString();
           }

           MDC.put(CORRELATION_ID_MDC, correlationId);
           try {
               chain.doFilter(request, response);
           } finally {
               MDC.remove(CORRELATION_ID_MDC);
           }
       }
   }
   ```

3. **Register Filter (Spring Boot)**
   ```java
   @Configuration
   public class FilterConfig {
       @Bean
       public FilterRegistrationBean<CorrelationIdFilter> correlationIdFilter() {
           FilterRegistrationBean<CorrelationIdFilter> bean =
               new FilterRegistrationBean<>(new CorrelationIdFilter());
           bean.setOrder(Ordered.HIGHEST_PRECEDENCE);
           return bean;
       }
   }
   ```

4. **Configure JSON Logging (logback-spring.xml)**
