5. **For Outgoing HTTP Calls**
   ```python
   import httpx
   from contextlib import asynccontextmanager

   @asynccontextmanager
   async def instrumented_httpx_client():
       async def inject_correlation_id(request):
           corr_id = get_correlation_id()
           if corr_id:
               request.headers['X-Correlation-ID'] = corr_id
           return request

       async with httpx.AsyncClient(event_hooks={
           'request': [inject_correlation_id]
       }) as client:
           yield client

