2. **Create Correlation ID Store & Setup**
   ```javascript
   import { AsyncLocalStorage } from 'async_hooks';
   import { v4 as uuidv4 } from 'uuid';
   import winston from 'winston';

   export const correlationStore = new AsyncLocalStorage();

   export function setCorrelationId(id) {
       correlationStore.getStore().correlation_id = id;
   }

   export function getCorrelationId() {
       return correlationStore.getStore()?.correlation_id || 'unknown';
   }

   // Initialize Winston with correlation ID
   export const logger = winston.createLogger({
       level: process.env.LOG_LEVEL || 'info',
       format: winston.format.combine(
           winston.format.timestamp(),
           winston.format.errors({ stack: true }),
           winston.format.json(),
           winston.format.printf(info => {
               const correlationId = getCorrelationId();
               return JSON.stringify({
                   timestamp: info.timestamp,
                   level: info.level,
                   message: info.message,
                   correlation_id: correlationId,
                   service: 'api-gateway',
                   ...info
               });
           })
       ),
       defaultMeta: {},
       transports: [
           new winston.transports.Console()
       ]
   });
   ```

3. **Create Express/Fastify Middleware**
   ```javascript
   // Express
   import express from 'express';

   app.use((req, res, next) => {
       const correlationId = req.headers['x-correlation-id'] || uuidv4();

       // Run handler in correlation context
       correlationStore.run({ correlation_id: correlationId }, () => {
           res.setHeader('X-Correlation-ID', correlationId);
           next();
       });
   });

   // Fastify
   import fastify from 'fastify';

   const app = fastify();

   app.addHook('onRequest', async (request, reply) => {
       const correlationId = request.headers['x-correlation-id'] || uuidv4();
       reply.header('X-Correlation-ID', correlationId);

       // Fastify doesn't auto-propagate AsyncLocalStorage,
       // so we manually set for request scope
       await correlationStore.run({ correlation_id: correlationId }, async () => {
           // request handling happens here
       });
   });
   ```

4. **Usage in Code**
   ```javascript
   app.get('/users/:id', (req, res) => {
       logger.info('Fetching user details');  // correlation_id auto-included
       const user = userService.getUser(req.params.id);
       res.json(user);
   });
   ```

5. **For Outgoing HTTP Calls**
   ```javascript
   import axios from 'axios';

   const httpClient = axios.create({
       interceptors: {
           request: {
               handlers: [(config) => {
                   const correlationId = getCorrelationId();
                   if (correlationId) {
                       config.headers['X-Correlation-ID'] = correlationId;
                   }
                   return config;
               }]
           }
       }
   });

   // Or manual setup for fetch
   async function fetchWithCorrelation(url, options = {}) {
       const correlationId = getCorrelationId();
       const headers = {
           ...options.headers,
           'X-Correlation-ID': correlationId
       };
       return fetch(url, { ...options, headers });
   }
   ```

6. **Using Pino (lighter alternative)**
   ```javascript
   import pino from 'pino';

   const logger = pino(
       {
           level: process.env.LOG_LEVEL || 'info',
           transport: {
               target: 'pino-pretty',
               options: {
                   colorize: true
               }
           }
       },
       pino.transport({
           target: 'pino/file',
           options: { destination: '/var/log/app.log' }
       })
   );

   // Wrap logger to add correlation ID
   const wrappedLog = (level, msg, meta = {}) => {
       const correlationId = getCorrelationId();
       logger[level]({ correlation_id: correlationId, ...meta }, msg);
   };
   ```

**Performance Notes:**
- AsyncLocalStorage: zero-copy, designed for high concurrency
- JSON serialization: ~0.05ms per log (pino is faster than winston)
- Middleware overhead: <0.05ms for header lookup and UUID generation
- Promise chain propagation: automatic via async/await, no manual context passing needed

