### A.2 Complete Python Implementation Example

**File: `app/logging_setup.py`**

```python
import logging
import json
import contextvars
import uuid
from datetime import datetime
from pythonjsonlogger import jsonlogger
from typing import Optional

# Context variable for correlation ID
correlation_id_var: contextvars.ContextVar[Optional[str]] = contextvars.ContextVar(
    'correlation_id', default=None
)

class CorrelationIdFilter(logging.Filter):
    """Add correlation ID from context to log records."""

    def filter(self, record):
        correlation_id = correlation_id_var.get()
        record.correlation_id = correlation_id or "unknown"
        return True

class CustomJsonFormatter(jsonlogger.JsonFormatter):
    """Custom JSON formatter with additional fields."""

    def add_fields(self, log_record, record, message_dict):
        super().add_fields(log_record, record, message_dict)
        log_record['service'] = 'api-service'
        log_record['environment'] = 'production'
        log_record['timestamp'] = datetime.utcnow().isoformat()

def setup_json_logging(service_name: str = "api-service") -> logging.Logger:
    """Configure structured JSON logging with correlation ID support."""

    logger = logging.getLogger()
    logger.setLevel(logging.INFO)

    # Console handler
    handler = logging.StreamHandler()
    formatter = CustomJsonFormatter(
        '%(timestamp)s %(level)s %(name)s %(message)s %(correlation_id)s'
    )
    handler.setFormatter(formatter)
    logger.addHandler(handler)

    # Add correlation ID filter
    logger.addFilter(CorrelationIdFilter())

    return logger

def set_correlation_id(cid: Optional[str] = None) -> str:
    """Set or generate correlation ID."""
    if cid is None:
        cid = str(uuid.uuid4())
    correlation_id_var.set(cid)
    return cid

def get_correlation_id() -> str:
    """Get current correlation ID."""
    return correlation_id_var.get() or "unknown"
