import { v4 as uuidv4 } from 'uuid';

interface CorrelationContext {
    correlation_id?: string;
}

export const correlationStore = new AsyncLocalStorage<CorrelationContext>();

export function setCorrelationId(id?: string): string {
    const correlationId = id || uuidv4();
    const store = correlationStore.getStore() || {};
    store.correlation_id = correlationId;
    correlationStore.enterWith(store);
    return correlationId;
}

export function getCorrelationId(): string {
    return correlationStore.getStore()?.correlation_id || 'unknown';
