#### **Java - Thread Pool & Scheduled Task Propagation**

**Challenge**: ThreadPoolExecutor doesn't inherit MDC by default; must wrap tasks.

```java
import org.slf4j.MDC;
import java.util.concurrent.*;

// ✓ CORRECT: Wrap task to capture MDC before execution
public class MDCExecutorService {
    private final ExecutorService executor;

    public MDCExecutorService(ExecutorService executor) {
        this.executor = executor;
    }

    public <T> Future<T> submit(Callable<T> task) {
        // Capture MDC in current thread
        Map<String, String> context = MDC.getCopyOfContextMap();

        return executor.submit(() -> {
            // Restore MDC in executor thread
            if (context != null) {
                MDC.setContextMap(context);
            }
            try {
                return task.call();
            } finally {
                MDC.clear();
            }
        });
    }

    public void execute(Runnable task) {
        Map<String, String> context = MDC.getCopyOfContextMap();

        executor.execute(() -> {
            if (context != null) {
                MDC.setContextMap(context);
            }
            try {
                task.run();
            } finally {
                MDC.clear();
            }
        });
    }
}

// ✓ CORRECT: Using custom Runnable wrapper
class MDCAwareRunnable implements Runnable {
    private final Runnable runnable;
    private final Map<String, String> mdcContext;

    public MDCAwareRunnable(Runnable runnable) {
        this.runnable = runnable;
        this.mdcContext = MDC.getCopyOfContextMap();
    }

    @Override
    public void run() {
        if (mdcContext != null) {
            MDC.setContextMap(mdcContext);
        }
        try {
            runnable.run();
        } finally {
            MDC.clear();
        }
    }
}

// Usage in service
public class AsyncService {
    private final ExecutorService executor = new MDCExecutorService(
        Executors.newFixedThreadPool(10)
    );

    public void processAsync(String data) {
        // MDC (including correlation_id) captured here
        logger.info("Starting async process");

        executor.execute(() -> {
            // Correlation ID automatically restored in thread pool thread
            logger.info("Background task running");  // Has correlation_id
        });
    }
}

// Unit test for thread pool propagation
@Test
