import (
    "context"
    "log/slog"
    "sync"
    "time"
)

// ✓ CORRECT: Goroutine automatically inherits context
func processRequest(ctx context.Context) {
    correlationID := GetCorrelationID(ctx)
    slog.InfoContext(ctx, "Starting request", "correlation_id", correlationID)

    // Launch background goroutine - it inherits parent context
    go func() {
        slog.InfoContext(ctx, "Background task started")  // ctx has correlation_id

        // Even nested goroutines inherit context
        go func() {
            time.Sleep(1 * time.Second)
            slog.InfoContext(ctx, "Nested task complete")  // Still has correlation_id
        }()
    }()
}

// ✓ CORRECT: Context passing through channels
func processWithChannels(ctx context.Context, items []string) {
    resultChan := make(chan string)

    // All goroutines receive same context
    for _, item := range items {
        go func(item string) {
            result := process(ctx, item)
            resultChan <- result
            slog.InfoContext(ctx, "Processed", "item", item)  // Has correlation_id
        }(item)
    }

    for range items {
        <-resultChan
    }
}

// ✓ CORRECT: WaitGroup with context
func processWithWaitGroup(ctx context.Context, count int) {
    var wg sync.WaitGroup

    for i := 0; i < count; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            slog.InfoContext(ctx, "Worker started", "worker_id", id)

            // Context automatically available
            correlationID := GetCorrelationID(ctx)
            slog.InfoContext(ctx, "Worker active", "correlation_id", correlationID)
        }(i)
    }

    wg.Wait()
    slog.InfoContext(ctx, "All workers complete")  // correlation_id present
}

