#### **Datadog Integration**

**Objective**: Correlation ID appears in Datadog trace context and links logs to traces.

```python
# Python: Datadog APM Integration
from ddtrace import tracer, patch
from ddtrace.contrib.logging import patch as patch_logging
from app.logging_setup import get_correlation_id, set_correlation_id
import logging

# Enable Datadog APM patches
patch_logging()
patch()

logger = logging.getLogger(__name__)

def datadog_correlation_middleware(request, call_next):
    """Middleware to integrate correlation ID with Datadog."""
    correlation_id = request.headers.get('X-Correlation-ID')
    if not correlation_id:
        correlation_id = str(uuid.uuid4())

    set_correlation_id(correlation_id)

    # Inject correlation ID into Datadog trace context
    # Datadog automatically links logs with dd.trace_id
    span = tracer.current_span()
    if span:
        span.set_tag('correlation_id', correlation_id)

    logger.info("Request started", extra={
        'correlation_id': correlation_id,
        'dd.trace_id': span.trace_id if span else None
    })

    response = await call_next(request)
    return response
