```java
// Java: Datadog APM Integration
import com.datadog.trace.api.GlobalTracer;
import com.datadog.trace.api.Tracer;
import org.slf4j.MDC;

public class DatadogCorrelationFilter implements Filter {
    @Override
    public void doFilter(ServletRequest request, ServletResponse response,
                        FilterChain chain) throws IOException, ServletException {
        HttpServletRequest httpRequest = (HttpServletRequest) request;
        String correlationId = httpRequest.getHeader("X-Correlation-ID");

        if (correlationId == null || correlationId.isEmpty()) {
            correlationId = UUID.randomUUID().toString();
        }

        MDC.put("correlation_id", correlationId);

        // Inject into Datadog span tags
        Tracer tracer = GlobalTracer.get();
        tracer.activeSpan().setTag("correlation_id", correlationId);

        try {
            chain.doFilter(request, response);
        } finally {
            MDC.remove("correlation_id");
        }
    }
}
