#### **Jaeger/Zipkin Integration**

**Objective**: Correlation ID propagates through Jaeger baggage and appears in spans.

```go
// Go: Jaeger Baggage Integration
import (
    "context"
    "log/slog"

    "github.com/jaegertracing/jaeger-client-go"
    "github.com/opentracing/opentracing-go"
)

const correlationIDKey = "correlation_id"

func jaegerCorrelationMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        correlationId := r.Header.Get("X-Correlation-ID")
        if correlationId == "" {
            correlationId = uuid.New().String()
        }

        // Extract Jaeger span from request context
        span, _ := opentracing.StartSpanFromContext(r.Context(), "http_request")
        defer span.Finish()

        // Set correlation ID as baggage (propagates to child spans)
        span.SetBaggageItem(correlationIDKey, correlationId)

        // Also set as span tag
        span.SetTag("correlation_id", correlationId)

        ctx := opentracing.ContextWithSpan(r.Context(), span)
        slog.InfoContext(ctx, "Request started",
            "correlation_id", correlationId)

        w.Header().Set("X-Correlation-ID", correlationId)
        next.ServeHTTP(w, r.WithContext(ctx))
    })
}

// Child spans automatically inherit baggage
func processWithChildSpan(ctx context.Context, spanName string) {
    span, _ := opentracing.StartSpanFromContext(ctx, spanName)
    defer span.Finish()

    // Get correlation ID from parent span's baggage
    correlationId := span.BaggageItem(correlationIDKey)

    slog.InfoContext(ctx, "Processing",
        "correlation_id", correlationId)
    // Correlation ID automatically propagates to downstream calls
}
