```python
# Python: Dual-logging during transition
from opentelemetry import trace
from app.logging_setup import get_correlation_id

def dual_logging_middleware(request, call_next):
    """Log both correlation_id (Phase 1-2) and OTEL trace_id (transition)."""
    correlation_id = request.headers.get('X-Correlation-ID')
    if not correlation_id:
        correlation_id = str(uuid.uuid4())

    set_correlation_id(correlation_id)

    # Get OTEL trace ID if instrumentation enabled
    span = trace.get_current_span()
    otel_trace_id = None
    otel_span_id = None
    if span and span.is_recording():
        context = span.get_span_context()
        otel_trace_id = format(context.trace_id, '032x')  # Convert to hex
        otel_span_id = format(context.span_id, '016x')

    logger.info("Request started", extra={
        'correlation_id': correlation_id,
        # Only include if OTEL instrumentation is active
        **({"otel.trace_id": otel_trace_id} if otel_trace_id else {}),
        **({"otel.span_id": otel_span_id} if otel_span_id else {})
    })

    response = await call_next(request)
    return response
```

```java
// Java: Dual-logging during transition
import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.GlobalOpenTelemetry;
import org.slf4j.MDC;

public class DualLoggingFilter implements Filter {
    @Override
    public void doFilter(ServletRequest request, ServletResponse response,
                        FilterChain chain) throws IOException, ServletException {
        HttpServletRequest httpRequest = (HttpServletRequest) request;
        String correlationId = httpRequest.getHeader("X-Correlation-ID");

        if (correlationId == null || correlationId.isEmpty()) {
            correlationId = UUID.randomUUID().toString();
        }

        MDC.put("correlation_id", correlationId);

        // Try to get OTEL trace ID if instrumentation active (optional)
        Tracer tracer = GlobalOpenTelemetry.getTracer("user-service");
        Span currentSpan = tracer.getCurrentSpan();
        if (currentSpan != null && currentSpan.isRecording()) {
            String otelTraceId = currentSpan.getSpanContext().getTraceId();
            String otelSpanId = currentSpan.getSpanContext().getSpanId();
            MDC.put("otel.trace_id", otelTraceId);
            MDC.put("otel.span_id", otelSpanId);
        }

        try {
            log.info("Request started");  // MDC auto-includes both IDs
            chain.doFilter(request, response);
        } finally {
            MDC.remove("correlation_id");
            MDC.remove("otel.trace_id");
            MDC.remove("otel.span_id");
        }
    }
}
```

